% SPDX-License-Identifier: EUPL-1.2
:- module(m__eu_data_protection_gdpr_binding_corporate_rules_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

implements(Key) :-
    citation(Key, _).

citation(eu_reg_2016_679_art_4_20, [label - 'Regulation (EU) 2016/679 (GDPR) Art 4(20) definition of binding corporate rules', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'means personal data protection policies which are adhered to by a controller or processor established on the territory of a Member State for transfers or a set of transfers of personal data to a controller or processor in one or more third countries within a group of undertakings, or group of enterprises engaged in a joint economic activity']).
citation(eu_reg_2016_679_art_47_2, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2) opening words (content binding corporate rules shall specify at least)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'The binding corporate rules referred to in paragraph 1 shall specify at least:']).
citation(eu_reg_2016_679_art_47_2_a, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(a) structure and contact details of the group and its members', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the structure and contact details of the group of undertakings, or group of enterprises engaged in a joint economic activity and of each of its members;']).
citation(eu_reg_2016_679_art_47_2_b, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(b) the data transfers or set of transfers', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the data transfers or set of transfers, including the categories of personal data, the type of processing and its purposes, the type of data subjects affected and the identification of the third country or countries in question;']).
citation(eu_reg_2016_679_art_47_2_c, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(c) legally binding nature, internally and externally', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'their legally binding nature, both internally and externally;']).
citation(eu_reg_2016_679_art_47_2_d, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(d) application of the general data protection principles', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the application of the general data protection principles, in particular purpose limitation, data minimisation, limited storage periods, data quality, data protection by design and by default, legal basis for processing, processing of special categories of personal data, measures to ensure data security, and the requirements in respect of onward transfers to bodies not bound by the binding corporate rules;']).
citation(eu_reg_2016_679_art_47_2_e, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(e) rights of data subjects and the means to exercise them', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the rights of data subjects in regard to processing and the means to exercise those rights, including the right not to be subject to decisions based solely on automated processing, including profiling in accordance with Article 22, the right to lodge a complaint with the competent supervisory authority and before the competent courts of the Member States in accordance with Article 79, and to obtain redress and, where appropriate, compensation for a breach of the binding corporate rules;']).
citation(eu_reg_2016_679_art_47_2_f, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(f) acceptance of liability for breaches by members not established in the Union', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the acceptance by the controller or processor established on the territory of a Member State of liability for any breaches of the binding corporate rules by any member concerned not established in the Union; the controller or the processor shall be exempt from that liability, in whole or in part, only if it proves that that member is not responsible for the event giving rise to the damage;']).
citation(eu_reg_2016_679_art_47_2_g, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(g) how information on the binding corporate rules is provided to data subjects', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'how the information on the binding corporate rules, in particular on the provisions referred to in points (d), (e) and (f) of this paragraph is provided to the data subjects in addition to Articles 13 and 14;']).
citation(eu_reg_2016_679_art_47_2_h, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(h) tasks of the data protection officer or other compliance monitoring person', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the tasks of any data protection officer designated in accordance with Article 37 or any other person or entity in charge of the monitoring compliance with the binding corporate rules within the group of undertakings, or group of enterprises engaged in a joint economic activity, as well as monitoring training and complaint-handling;']).
citation(eu_reg_2016_679_art_47_2_i, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(i) the complaint procedures', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the complaint procedures;']).
citation(eu_reg_2016_679_art_47_2_j, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(j) mechanisms for verification of compliance', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the mechanisms within the group of undertakings, or group of enterprises engaged in a joint economic activity for ensuring the verification of compliance with the binding corporate rules. Such mechanisms shall include data protection audits and methods for ensuring corrective actions to protect the rights of the data subject.']).
citation(eu_reg_2016_679_art_47_2_k, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(k) mechanisms for reporting and recording changes to the rules', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the mechanisms for reporting and recording changes to the rules and reporting those changes to the supervisory authority;']).
citation(eu_reg_2016_679_art_47_2_l, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(l) cooperation mechanism with the supervisory authority', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the cooperation mechanism with the supervisory authority to ensure compliance by any member of the group of undertakings, or group of enterprises engaged in a joint economic activity, in particular by making available to the supervisory authority the results of verifications of the measures referred to in point (j);']).
citation(eu_reg_2016_679_art_47_2_m, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(m) mechanisms for reporting third-country legal requirements', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the mechanisms for reporting to the competent supervisory authority any legal requirements to which a member of the group of undertakings, or group of enterprises engaged in a joint economic activity is subject in a third country which are likely to have a substantial adverse effect on the guarantees provided by the binding corporate rules; and']).
citation(eu_reg_2016_679_art_47_2_n, [label - 'Regulation (EU) 2016/679 (GDPR) Art 47(2)(n) appropriate data protection training', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the appropriate data protection training to personnel having permanent or regular access to personal data.']).

test(the_definition_key_is_recorded) :-
    implements(eu_reg_2016_679_art_4_20).
test(the_training_point_key_is_recorded) :-
    implements(eu_reg_2016_679_art_47_2_n).

test(a_shortened_key_is_not_recorded, fail) :-
    implements(art_4_20).
